/* Site navigation for knowledge pages (specs/site-navigation.md).
 *
 * Included by every live page as the last thing in <body>:
 *   <script defer src="../../../site-nav.js?v=…"></script>   (+ site-nav.css in <head>)
 * It loads site-nav-data.js (generated by scripts/build-site-nav.cjs from pages.config.js) and
 *   1. renders a breadcrumb  首页 › <category> › <subtopic>  linking to the home views, placed right
 *      above the page title (or inside an element marked data-site-nav), in the page's language;
 *   2. turns exact mentions of other live pages' titles into links:
 *      zh 《exact title》, en “Exact Title” (curly quotes), or <cite>Exact Title</cite>.
 * Text inside links, headings, buttons, form controls, svg/canvas, the provenance label and
 * anything under [data-no-autolink] is left alone, and a page never links to itself.
 * A debounced MutationObserver re-runs both after the page re-renders (language switch).
 * Pages built from the site template (<html data-template>, specs/site-template.md) already carry a static
 * breadcrumb and build-time links, so the script does nothing there.
 */
(function (global) {
  'use strict';

  /* ---------- pure part (also loaded by tests/site-nav.cjs in node) ---------- */
  function escapeRe(s) { return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); }
  // ' and ’ are both used in English copy; a title matches with either.
  function titleRe(s) { return escapeRe(s).replace(/['’]/g, "['’]"); }
  function normTitle(s) { return s.replace(/’/g, "'"); }
  function slugOf(p) { return p[0] || p[1].split('/').filter(Boolean).pop(); }

  // data: SITE_NAV_DATA. Returns { re, zh: {title: page}, en: {normTitle: page} }.
  function buildMatcher(data) {
    var zh = {}, en = {}, zhList = [], enList = [];
    data.pages.forEach(function (p) {
      var page = { slug: slugOf(p), path: p[1], zh: p[2], en: p[3], cat: p[4], sub: p[5] };
      if (p[2] && !zh[p[2]]) { zh[p[2]] = page; zhList.push(p[2]); }
      if (p[3] && !en[normTitle(p[3])]) { en[normTitle(p[3])] = page; enList.push(p[3]); }
    });
    var byLen = function (a, b) { return b.length - a.length; };
    zhList.sort(byLen); enList.sort(byLen);
    // 《title》  or  “Title” / “Title,” / “Title.” (US punctuation inside the closing quote)
    var src = [];
    if (zhList.length) src.push('《(' + zhList.map(escapeRe).join('|') + ')》');
    if (enList.length) src.push('“(' + enList.map(titleRe).join('|') + ')[,.]?”');
    return { re: src.length ? new RegExp(src.join('|'), 'g') : null, zh: zh, en: en };
  }

  // Matches in one string: [{ index, length, title, page }] where index/length cover the title
  // text only (the brackets and quotes stay outside the link). selfPath and the page's
  // noAutolink titles are skipped.
  function findMatches(text, matcher, selfPath, excluded) {
    var out = [];
    if (!matcher.re || (text.indexOf('《') === -1 && text.indexOf('“') === -1)) return out;
    matcher.re.lastIndex = 0;
    var m;
    while ((m = matcher.re.exec(text))) {
      var title = m[1] || m[2];
      var page = m[1] ? matcher.zh[m[1]] : matcher.en[normTitle(m[2])];
      if (!page || page.path === selfPath) continue;
      if (excluded && excluded.indexOf(normTitle(title)) !== -1) continue;
      out.push({ index: m.index + 1, length: title.length, title: title, page: page });
    }
    return out;
  }
  // A whole <cite> whose text is exactly a title.
  function citeMatch(text, matcher, selfPath, excluded) {
    var t = text.trim();
    var page = matcher.zh[t] || matcher.en[normTitle(t)];
    if (!page || page.path === selfPath) return null;
    if (excluded && excluded.indexOf(normTitle(t)) !== -1) return null;
    return page;
  }

  var core = { buildMatcher: buildMatcher, findMatches: findMatches, citeMatch: citeMatch };
  if (typeof module === 'object' && module.exports) { module.exports = core; return; }
  if (!global.document || global.SiteNav) return;

  /* ---------- page part ---------- */
  var doc = global.document;
  if (doc.documentElement && doc.documentElement.hasAttribute && doc.documentElement.hasAttribute('data-template')) {
    global.SiteNav = { skipped: 'data-template', report: function () { return []; }, page: function () { return null; }, rescan: function () {} };
    // A lesson whose runtime does not translate data-i18n-aria gets its static breadcrumb without an aria-label
    // (specs/site-template.md §3c). Name it here, as this file does on hand-written pages, and follow <html lang>.
    var crumb = doc.querySelector('nav.site-nav');
    if (crumb && !crumb.hasAttribute('aria-label')) {
      var nameCrumb = function () {
        var l = (doc.documentElement.getAttribute('lang') || '').toLowerCase().indexOf('en') === 0 ? 'en' : 'zh';
        var v = l === 'en' ? 'Breadcrumb' : '页面位置';
        if (crumb.getAttribute('aria-label') !== v) crumb.setAttribute('aria-label', v);
      };
      nameCrumb();
      if (global.MutationObserver) new global.MutationObserver(nameCrumb).observe(doc.documentElement, { attributes: true, attributeFilter: ['lang'] });
    }
    // A converted lesson that does not load lesson-shell.css (Phase 3 batch B): site-nav.css centres the linked-from
    // block with the page's --gutter or 16px, but 55 of these pages narrow their .step side padding to 12px in their
    // own media query, so at 390/320 the block sat 4px further in than the steps. Use a step's own side padding.
    if (doc.documentElement.getAttribute('data-template') === 'lesson' && !doc.querySelector('link[href*="lesson-shell.css"]') && global.getComputedStyle) {
      var xref = doc.querySelector('section.site-xref'), xstep = doc.getElementById('step1') || doc.querySelector('.step');
      if (xref && xstep) {
        var alignXref = function () {
          var cs = global.getComputedStyle(xstep);
          xref.style.paddingLeft = cs.paddingLeft;
          xref.style.paddingRight = cs.paddingRight;
        };
        alignXref();
        global.addEventListener('resize', alignXref);
      }
    }
    // A converted lesson that does not load lesson-shell.js (Phase 3 batch B): on the hand-written page the first
    // step's nav pill was lit at load on most window sizes, because this file mounted the breadcrumb late and step 0
    // sat inside the scroll spy's band for the first observation. The static breadcrumb puts step 0 at its final
    // place from the start, so the spy lights nothing. As lesson-shell.js does for batch A: on a plain navigation at
    // scroll 0 with no #fragment and nothing lit, light the first item; the spy's next match replaces it.
    if (doc.documentElement.getAttribute('data-template') === 'lesson' && !doc.querySelector('script[src*="lesson-shell.js"]') && global.addEventListener) {
      global.addEventListener('load', function () {
        var raf = global.requestAnimationFrame || function (f) { return setTimeout(f, 16); };
        raf(function () { raf(function () {
          var perf = global.performance, e = perf && perf.getEntriesByType && perf.getEntriesByType('navigation')[0];
          if (e && e.type && e.type !== 'navigate') return;
          if (global.location.hash || global.scrollY > 0) return;
          var stepNav = doc.querySelector('.step-nav');
          if (!stepNav || stepNav.querySelector('.active')) return;
          var first = stepNav.querySelector('a[href^="#"], .nav-step');
          if (!first) return;
          first.classList.add('active');
          // Some of these pages have no working spy (nothing ever lights live). There the default would stay on
          // step 0 for good, so it is taken back once step 0 has scrolled entirely out of the window while it is
          // still the only lit item. As soon as anything else is lit, the spy owns the nav and this stops. Not
          // earlier: the hand-written pages kept pill 0 lit until the spy lit step 1, and a spy's band lies inside
          // the window, so step 1 has crossed it by the time step 0 is gone (taking it back at 40 % of the window
          // left no pill lit for a stretch on pages whose spy lights step 1 later; Phase 3b review).
          var step0 = doc.getElementById((first.getAttribute('href') || '').replace(/^#/, ''));
          var onScroll = function () {
            var lit = stepNav.querySelectorAll('.active');
            if (lit.length !== 1 || lit[0] !== first) { global.removeEventListener('scroll', onScroll); return; }
            var past = step0 ? step0.getBoundingClientRect().bottom < 0 : global.scrollY > global.innerHeight;
            if (past) { first.classList.remove('active'); global.removeEventListener('scroll', onScroll); }
          };
          global.addEventListener('scroll', onScroll, { passive: true });
        }); });
      });
    }
    return;
  }
  var me = doc.currentScript;
  if (!me || !me.src) return;
  var rootURL = new URL('.', me.src);
  var version = (me.src.match(/[?&]v=([^&#]+)/) || [])[1] || '';
  var UI = {
    zh: { home: '首页', label: '页面位置' },
    en: { home: 'Home', label: 'Breadcrumb' }
  };
  var SKIP = 'a,h1,h2,h3,h4,h5,h6,button,label,input,select,option,textarea,summary,svg,canvas,script,style,noscript,' +
    'code,pre,kbd,samp,[contenteditable],[role="button"],[role="link"],[role="tab"],[role="option"],[role="menuitem"],' +
    '[aria-hidden="true"],.page-provenance,.site-nav,[data-no-autolink]';

  // Where this page sits relative to the site root (directory part, e.g. "computing/systems/x/").
  var here = decodeURIComponent(location.pathname);
  var rootPath = decodeURIComponent(rootURL.pathname);
  var pageDir = here.indexOf(rootPath) === 0 ? here.slice(rootPath.length).replace(/[^/]*$/, '') : null;
  var up = pageDir == null ? rootURL.href : (new Array(pageDir.split('/').filter(Boolean).length + 1).join('../') || './');

  var data, matcher, page, excluded = [], nav, created = [], observer, timer = 0, pending = [];

  function lang() {
    var l = (doc.documentElement.getAttribute('lang') || '').toLowerCase();
    if (l.indexOf('zh') === 0) return 'zh';
    if (l.indexOf('en') === 0) return 'en';
    try { var s = localStorage.getItem('knowledge-lang'); if (s === 'zh' || s === 'en') return s; } catch (e) {}
    return 'zh';
  }
  function name(v) { var l = lang(); return v ? (v[l] || v.zh || v.en || '') : ''; }
  function homeHref(q) { return (up === './' && q ? '' : up) + (q || ''); }

  /* Breadcrumb: nodes are built once; a language change only rewrites their text. */
  function buildNav() {
    nav = doc.createElement('nav');
    nav.className = 'site-nav';
    nav.setAttribute('data-no-autolink', '');
    var ol = doc.createElement('ol');
    var items = [{ key: 'home', href: homeHref('') }, { key: 'cat', href: homeHref('?category=' + encodeURIComponent(page.cat)) }];
    if (page.sub) items.push({ key: 'sub', href: homeHref('?category=' + encodeURIComponent(page.cat) + '&subtopic=' + encodeURIComponent(page.sub)) });
    items.forEach(function (it) {
      var li = doc.createElement('li'), a = doc.createElement('a');
      a.href = it.href; a.setAttribute('data-crumb', it.key);
      li.appendChild(a); ol.appendChild(li);
    });
    nav.appendChild(ol);
    textNav();
  }
  function textNav() {
    var l = lang();
    nav.setAttribute('aria-label', UI[l].label);
    nav.setAttribute('lang', l === 'zh' ? 'zh-CN' : 'en');
    nav.querySelectorAll('a').forEach(function (a) {
      var k = a.getAttribute('data-crumb');
      var text = k === 'home' ? UI[l].home : k === 'cat' ? name(data.cats[page.cat]) : name(data.subs[page.cat + '/' + page.sub]);
      if (a.textContent !== text) a.textContent = text;
    });
  }
  function mountNav() {
    if (nav.isConnected) return;
    var host = doc.querySelector('[data-site-nav]');
    if (host) { host.appendChild(nav); return; }
    var h1 = doc.querySelector('h1');
    if (!h1 || !h1.parentNode) { doc.body.insertBefore(nav, doc.body.firstChild); return; }
    // Above the title, and above a kicker/eyebrow line that introduces it.
    var before = h1, prev = h1.previousElementSibling;
    if (prev && /(^|\s)(kicker|eyebrow)(\s|$)/.test(prev.className || '')) before = prev;
    before.parentNode.insertBefore(nav, before);
  }

  /* Auto-links */
  function relHref(p) { return homeHref(p.path); }
  function linkFor(match) {
    var a = doc.createElement('a');
    a.className = 'site-autolink';
    a.href = relHref(match.page);
    a.setAttribute('data-site-autolink', match.page.slug);
    a.textContent = match.title;
    return a;
  }
  function skipped(el) { return !el || !!el.closest(SKIP); }
  function linkText(node) {
    var text = node.nodeValue, ms = findMatches(text, matcher, page ? page.path : pageDir, excluded);
    if (!ms.length) return;
    var frag = doc.createDocumentFragment(), at = 0;
    ms.forEach(function (m) {
      if (m.index > at) frag.appendChild(doc.createTextNode(text.slice(at, m.index)));
      var a = linkFor(m); frag.appendChild(a); created.push(a);
      at = m.index + m.length;
    });
    if (at < text.length) frag.appendChild(doc.createTextNode(text.slice(at)));
    node.parentNode.replaceChild(frag, node);
  }
  function scan(rootEl) {
    if (!rootEl || !rootEl.isConnected) return;
    var el = rootEl.nodeType === 1 ? rootEl : rootEl.parentElement;
    if (!el || skipped(el)) return;
    var texts = [];
    var walker = doc.createTreeWalker(el, NodeFilter.SHOW_TEXT, {
      acceptNode: function (n) {
        var v = n.nodeValue;
        if (v.indexOf('《') === -1 && v.indexOf('“') === -1) return NodeFilter.FILTER_REJECT;
        return skipped(n.parentElement) ? NodeFilter.FILTER_REJECT : NodeFilter.FILTER_ACCEPT;
      }
    });
    while (walker.nextNode()) texts.push(walker.currentNode);
    texts.forEach(linkText);
    var cites = el.matches && el.matches('cite') ? [el] : Array.prototype.slice.call(el.querySelectorAll('cite'));
    cites.forEach(function (c) {
      if (skipped(c.parentElement) || c.closest('[data-no-autolink]') || c.querySelector('a')) return;
      var p = citeMatch(c.textContent, matcher, page ? page.path : pageDir, excluded);
      if (!p) return;
      var a = linkFor({ page: p, title: c.textContent });
      c.textContent = ''; c.appendChild(a); created.push(a);
    });
  }

  /* Re-run after the page re-renders. Our own writes happen with the observer disconnected. */
  function run(roots) {
    if (observer) observer.disconnect();
    if (nav) { mountNav(); textNav(); }
    (roots || [doc.body]).forEach(scan);
    created = created.filter(function (a) { return a.isConnected; });
    if (observer) {
      observer.takeRecords();
      observer.observe(doc.body, { childList: true, subtree: true, characterData: true });
      observer.observe(doc.documentElement, { attributes: true, attributeFilter: ['lang'] });
    }
  }
  function interesting(n) {
    var v = n.nodeType === 3 ? n.nodeValue : n.nodeType === 1 ? n.textContent : '';
    return v && (v.indexOf('《') !== -1 || v.indexOf('“') !== -1 || (n.nodeType === 1 && (n.matches('cite') || n.querySelector('cite'))));
  }
  function onMutations(records) {
    var want = false;
    records.forEach(function (r) {
      if (r.type === 'attributes') { want = true; return; }
      if (r.type === 'characterData') { if (interesting(r.target)) { pending.push(r.target); want = true; } return; }
      if (nav && !nav.isConnected) want = true;
      r.addedNodes.forEach(function (n) { if (interesting(n)) { pending.push(n); want = true; } });
    });
    if (!want || timer) return;
    timer = setTimeout(function () {
      timer = 0;
      var roots = pending.filter(function (n, i) { return pending.indexOf(n) === i; });
      pending = [];
      run(roots);
    }, 60);
  }

  function start() {
    data = global.SITE_NAV_DATA;
    if (!data || !data.pages) return;
    matcher = buildMatcher(data);
    for (var i = 0; i < data.pages.length; i++) {
      if (data.pages[i][1] === pageDir) { var p = data.pages[i]; page = { slug: slugOf(p), path: p[1], cat: p[4], sub: p[5] }; break; }
    }
    (data.noAutolink || []).forEach(function (e) { if (e[0] === pageDir) excluded.push(normTitle(e[1])); });
    if (page && data.cats[page.cat]) buildNav();
    if (global.MutationObserver) observer = new MutationObserver(onMutations);
    run();
  }

  global.SiteNav = {
    // For tests and audits: every auto-link currently on the page, with its context.
    report: function () {
      return created.filter(function (a) { return a.isConnected; }).map(function (a) {
        var block = a.closest('p,li,td,th,dd,dt,figcaption,blockquote,div') || a.parentElement;
        return { title: a.textContent, href: a.getAttribute('href'), slug: a.getAttribute('data-site-autolink'),
          context: (block ? block.textContent : '').replace(/\s+/g, ' ').trim().slice(0, 400) };
      });
    },
    page: function () { return page || null; },
    rescan: function () { run(); }
  };

  if (global.SITE_NAV_DATA) start();
  else {
    var s = doc.createElement('script');
    // The data changes whenever a page is registered; an hourly key keeps a cached copy at most an hour old.
    s.src = new URL('site-nav-data.js?v=' + version + '-' + Math.floor(Date.now() / 3600000), rootURL).href;
    s.onload = start;
    doc.head.appendChild(s);
  }
})(typeof window !== 'undefined' ? window : this);
